//! Nodes and links (DESIGN.md §6.1, §6.2).

use std::collections::BTreeMap;
use std::fmt;
use std::str::FromStr;

use model::{Id, ParamValue, Rate, TimeUnit};
use serde::{Deserialize, Serialize};

/// A node's identity inside one schema.
///
/// Free-form rather than a `namespace:path`: these are generated by the editor
/// and only have to be unique within the file.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct NodeId(String);

impl NodeId {
    pub fn new(text: impl Into<String>) -> Self {
        Self(text.into())
    }

    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.0.trim().is_empty()
    }
}

impl fmt::Display for NodeId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // `pad`, not `write_str`, so `{:<14}` lines node ids up in a column.
        f.pad(&self.0)
    }
}

impl FromStr for NodeId {
    type Err = std::convert::Infallible;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        Ok(Self::new(text))
    }
}

impl From<&str> for NodeId {
    fn from(text: &str) -> Self {
        Self::new(text)
    }
}

/// An amount per unit of time, as written in a schema file.
///
/// Rule 4 keeps the core in per-tick `f64`, but a schema is read and shared by
/// people, so the file says which unit it means and [`Self::rate`] converts.
/// Leaving `unit` out means per minute, matching the editor's default.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Flow {
    pub amount: f64,
    #[serde(default)]
    pub unit: TimeUnit,
}

impl Flow {
    #[must_use]
    pub fn new(amount: f64, unit: TimeUnit) -> Self {
        Self { amount, unit }
    }

    #[must_use]
    pub fn rate(self) -> Rate {
        Rate::per(self.unit, self.amount)
    }
}

/// A machine running one recipe, some number of times over.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MachineNode {
    pub machine: Id,
    pub recipe: Id,
    /// Overrides for the machine's parameters; anything absent keeps its
    /// default.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub params: BTreeMap<String, ParamValue>,
    /// How many machines stand here. Absent means the solver may use as many
    /// as it likes, which is how an unconstrained plan is drawn.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub count: Option<f64>,
    /// Role to network name, e.g. `energy` → `main`. The named network's kind
    /// must match what the machine declares for that role.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub networks: BTreeMap<String, String>,
}

/// Something entering the schema from outside: a farm, a chest, a purchase.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SourceNode {
    pub resource: Id,
    /// Absent means unlimited.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rate: Option<Flow>,
}

/// What the schema is for. Anything beyond `target` is surplus.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct OutputNode {
    pub resource: Id,
    /// A ceiling on demand, not a promise: the solver maximises up to it and
    /// reports a shortfall when it cannot get there.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub target: Option<Flow>,
}

/// A chest, a barrel, an ME network: many in, many out, nothing changed.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct HubNode {}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct NoteNode {
    #[serde(default)]
    pub text: String,
}

/// What a node actually is.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum NodeKind {
    Machine(MachineNode),
    Source(SourceNode),
    Output(OutputNode),
    Hub(HubNode),
    Note(NoteNode),
}

impl NodeKind {
    #[must_use]
    pub const fn type_name(&self) -> &'static str {
        match self {
            Self::Machine(_) => "machine",
            Self::Source(_) => "source",
            Self::Output(_) => "output",
            Self::Hub(_) => "hub",
            Self::Note(_) => "note",
        }
    }

    /// Notes are decoration: they take no part in the calculation.
    #[must_use]
    pub const fn is_decorative(&self) -> bool {
        matches!(self, Self::Note(_))
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Node {
    pub id: NodeId,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
    /// Canvas position, kept so the editor's layout survives a round trip.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub position: Option<[f32; 2]>,
    #[serde(flatten)]
    pub kind: NodeKind,
}

impl Node {
    pub fn new(id: impl Into<NodeId>, kind: NodeKind) -> Self {
        Self {
            id: id.into(),
            label: None,
            position: None,
            kind,
        }
    }

    #[must_use]
    pub fn machine(&self) -> Option<&MachineNode> {
        match &self.kind {
            NodeKind::Machine(machine) => Some(machine),
            _ => None,
        }
    }
}

/// One resource flowing from one node to another.
///
/// Ports are implicit: a link is identified by the resource it carries, which
/// for a machine follows from its recipe. Several links may meet at the same
/// place and the solver decides how the flow divides, so there are no splitter
/// or merger nodes (DESIGN.md §6.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Link {
    pub from: NodeId,
    pub to: NodeId,
    pub resource: Id,
    /// Transport type from a plugin, which brings its own capacity.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub transport: Option<Id>,
    /// An explicit ceiling on this link, independent of any transport.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub capacity: Option<Flow>,
}

impl Link {
    pub fn new(from: impl Into<NodeId>, to: impl Into<NodeId>, resource: Id) -> Self {
        Self {
            from: from.into(),
            to: to.into(),
            resource,
            transport: None,
            capacity: None,
        }
    }
}

/// A named energy or stress network. Machines join it by name instead of
/// being wired up with lines (DESIGN.md §6.2).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Network {
    /// The kind of network, e.g. `mekanism:joules` or `create:kinetic`.
    pub kind: Id,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
}
